import { test, expect } from '@playwright/test';

test('drag task between columns', async ({ page }) => {
  await page.goto('/project/1');
  await page.waitForSelector('[data-column-id="todo"]');

  const task = page.locator('[data-task-id="1"]').first();
  const targetColumn = page.locator('[data-column-id="in-progress"]');

  await task.dragTo(targetColumn);

  await expect(page.locator('[data-column-id="in-progress"] [data-task-id="1"]')).toBeVisible();
});
